inline ::flatbuffers::Offset<TFN> CreateTFN(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PLACE_ID = 0,
    tfnFacilityType FACILITY_TYPE = tfnFacilityType_UNSPECIFIED,
    ::flatbuffers::Offset<::flatbuffers::String> NAME = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TFNDesignator>>> DESIGNATORS = 0,
    ::flatbuffers::Offset<::flatbuffers::String> COUNTRY_CODE = 0,
    double ELEVATION_M = 0.0,
    bool ELEVATION_PUBLISHED = false,
    double MAGNETIC_VARIATION_DEG = 0.0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<TFNOperatingSurface>>> OPERATING_SURFACES = 0,
    double MAXIMUM_DRAFT_M = 0.0,
    double ANCHORAGE_DEPTH_M = 0.0,
    ::flatbuffers::Offset<::flatbuffers::String> HARBOR_TYPE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SHELTER_AFFORDED = 0,
    ::flatbuffers::Offset<TFNProvenance> SOURCE = 0) {
  TFNBuilder builder_(_fbb);
  builder_.add_ANCHORAGE_DEPTH_M(ANCHORAGE_DEPTH_M);
  builder_.add_MAXIMUM_DRAFT_M(MAXIMUM_DRAFT_M);
  builder_.add_MAGNETIC_VARIATION_DEG(MAGNETIC_VARIATION_DEG);
  builder_.add_ELEVATION_M(ELEVATION_M);
  builder_.add_SOURCE(SOURCE);
  builder_.add_SHELTER_AFFORDED(SHELTER_AFFORDED);
  builder_.add_HARBOR_TYPE(HARBOR_TYPE);
  builder_.add_OPERATING_SURFACES(OPERATING_SURFACES);
  builder_.add_COUNTRY_CODE(COUNTRY_CODE);
  builder_.add_DESIGNATORS(DESIGNATORS);
  builder_.add_NAME(NAME);
  builder_.add_PLACE_ID(PLACE_ID);
  builder_.add_ID(ID);
  builder_.add_ELEVATION_PUBLISHED(ELEVATION_PUBLISHED);
  builder_.add_FACILITY_TYPE(FACILITY_TYPE);
  return builder_.Finish();
}

