inline const TFN *GetTFN(const void *buf) {
  return ::flatbuffers::GetRoot<TFN>(buf);
}

inline const TFN *GetSizePrefixedTFN(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<TFN>(buf);
}

inline const char *TFNIdentifier() {
  return "$TFN";
}

inline bool TFNBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TFNIdentifier());
}

inline bool SizePrefixedTFNBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TFNIdentifier(), true);
}

template <bool B = false>
inline bool VerifyTFNBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<TFN>(TFNIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedTFNBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<TFN>(TFNIdentifier());
}

inline void FinishTFNBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TFN> root) {
  fbb.Finish(root, TFNIdentifier());
}

inline void FinishSizePrefixedTFNBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TFN> root) {
  fbb.FinishSizePrefixed(root, TFNIdentifier());
}

